#!/usr/bin/env python3
"""Instalador del sistema multi-LLM para Vela."""
import os, base64, shutil
from datetime import datetime

VERA_DIR = os.path.expanduser('~/Desktop/vela/backend/vera')
BACKUP_DIR = os.path.join(VERA_DIR, '_backup_' + datetime.now().strftime('%Y%m%d_%H%M%S'))

if not os.path.exists(VERA_DIR):
    print(f"ERROR: No existe {VERA_DIR}")
    exit(1)

os.makedirs(BACKUP_DIR, exist_ok=True)
print(f"Backup en: {BACKUP_DIR}\n")

FILES_B64 = {
    "llm_base.py": "",
    "llm_claude.py": "",
    "llm_openai.py": "",
    "llm_gemini.py": "",
    "llm_perplexity.py": "",
    "llm_router.py": "",
}

print(f"Creando archivos en {VERA_DIR}/")
for name, b64 in FILES_B64.items():
    path = os.path.join(VERA_DIR, name)
    if os.path.exists(path):
        shutil.copy(path, os.path.join(BACKUP_DIR, name))
        print(f"  ~ {name} (backup hecho)")
    content = base64.b64decode(b64).decode('utf-8')
    with open(path, 'w') as f:
        f.write(content)
    print(f"  + {name}")

print("\nOK Instalacion completa")
print("\nProximos pasos:")
print("1. pip install anthropic requests --break-system-packages  (si no estan)")
print("2. Reinicia el backend (Ctrl+C y vuelve a ejecutar uvicorn)")
print("3. Pega lo que diga el backend al arrancar")
